#!/usr/bin/env bash
set -euo pipefail

profile=${1:?usage: publish-firmware.sh PROFILE}
[[ $profile =~ ^[A-Za-z0-9_-]+$ ]] || { echo '::error::Invalid profile name' >&2; exit 1; }
[[ -f openwrt_bin/.build-start ]] || { echo '::error::Build start marker is missing' >&2; exit 1; }
[[ -f openwrt_bin/build_info ]] || { echo '::error::Build manifest is missing' >&2; exit 1; }

sudo chown -R "$(id -u):$(id -g)" openwrt_bin stcache
artifact_dir=$(mktemp -d "${RUNNER_TEMP:-$PWD}/firmware.XXXXXX")
mapfile -d '' -t built_images < <(
  find -L openwrt_bin/targets -type f -name '*sysupgrade.itb' \
    -newer openwrt_bin/.build-start -print0
)
if (( ${#built_images[@]} == 0 )); then
  echo '::error::No sysupgrade image was generated by this build' >&2
  exit 1
fi
for image in "${built_images[@]}"; do
  [[ -s $image ]] || { echo "::error::Empty firmware image: $image" >&2; exit 1; }
  install -m 644 "$image" "$artifact_dir/"
done

profile_json=$(find -L openwrt_bin/targets -type f -name profiles.json \
  -newer openwrt_bin/.build-start -print -quit)
[[ -n $profile_json ]] || { echo '::error::No current profiles.json was generated' >&2; exit 1; }
version_code=$(jq -er '.version_code | select(. != null) | tostring | select(length > 0)' "$profile_json")
version="${profile}_$(date +'%Y.%m.%d')_${version_code}"
if [[ -n ${GITHUB_RUN_ID:-} ]]; then version="${version}_run${GITHUB_RUN_ID}-${GITHUB_RUN_ATTEMPT:-1}"; fi
builder_image_id=$(docker inspect DK --format '{{.Image}}')
[[ -n $builder_image_id ]] || { echo '::error::Builder container image ID is missing' >&2; exit 1; }
printf '\nRelease: %s\nBuilder container image ID: %s\n' \
  "$version" "$builder_image_id" >> openwrt_bin/build_info
cp openwrt_bin/build_info "$artifact_dir/build_info.txt"
(
  cd "$artifact_dir"
  sha256sum -- *sysupgrade.itb build_info.txt > SHA256SUMS
  sha256sum -c SHA256SUMS
)
{ printf '## %s\n\n' "$version"; cat "$artifact_dir/build_info.txt"; } > "$artifact_dir/release-notes.md"

gh release create "$version" "$artifact_dir"/*sysupgrade.itb "$artifact_dir/SHA256SUMS" \
  "$artifact_dir/build_info.txt" --title "$version" --notes-file "$artifact_dir/release-notes.md"

releases=$(gh release list --limit 1000 --json tagName,publishedAt,isDraft) || {
  echo '::warning::Release created, but old release listing failed; retention was skipped' >&2
  exit 0
}
mapfile -t old_releases < <(
  jq -r --arg prefix "${profile}_" \
    '.[] | select(.isDraft == false and (.tagName | startswith($prefix))) | [.publishedAt, .tagName] | @tsv' \
    <<< "$releases" | sort -r | tail -n +4 | cut -f2-
)
for tag in "${old_releases[@]}"; do
  if [[ -n $tag ]] && ! gh release delete "$tag" --cleanup-tag --yes; then
    echo "::warning::Release $tag could not be removed" >&2
  fi
done
